def err(u,cap,extra=False):
    u=I(u)
    B=[sourcefloor+I('113.67')*ef(I('.5'),u)]+source_bounds(u)
    if u.l>I(59).ln().r and u.r<=I('2.169e25').ln().l:
        B+=[u*u/(8*PI)*ef(I('.5'),u)]
    if u.l>=10 and u.r<=(I(10**13).ln()).l:
        B+=[I('.791')*ef(I('.5'),u)]
    if u.l>I(10**9).ln().r:
