    return T

def ch(u,with_weight=False,adaptive=False):
    T=evalT(u,adaptive)
    y=(T/(2*PI)).ln()
    c=y*y/(2*PI)-y/(6*PI)
    return PI/(T-1)+c*ef(I('.5'),u)+(0 if with_weight else PI**2/(3*T**2))

